/** Generate the bundled sample PDFs (public/samples/) with pdf-lib.
 *  Run: npm run samples */
import { mkdirSync, writeFileSync } from "node:fs";
import { PDFDocument, StandardFonts, rgb } from "pdf-lib";

const A4 = [595.28, 841.89];
const OUT = new URL("../public/samples/", import.meta.url).pathname;

const PALETTE = [
  rgb(0.90, 0.96, 0.98),
  rgb(0.99, 0.96, 0.90),
  rgb(0.93, 0.98, 0.94),
  rgb(0.97, 0.93, 0.98),
  rgb(0.95, 0.96, 0.99),
];

const LOREM = [
  "This sample file is generated by scripts/make-samples.mjs so you can try",
  "every feature of the Local PDF Toolkit without using your own documents.",
  "Extract a few pages, delete some, rotate one sideways, then export the",
  "result - the output PDF is assembled in your browser and never uploaded.",
];

async function decorate(doc, { title, subtitle, footer }) {
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const n = doc.getPageCount();
  doc.getPages().forEach((page, i) => {
    const { width, height } = page.getSize();
    page.drawRectangle({
      x: 0,
      y: height - 90,
      width,
      height: 90,
      color: PALETTE[i % PALETTE.length],
    });
    page.drawText(title, { x: 48, y: height - 58, size: 24, font: bold, color: rgb(0.1, 0.15, 0.2) });
    page.drawText(subtitle, { x: 48, y: height - 78, size: 11, font, color: rgb(0.35, 0.4, 0.45) });
    page.drawRectangle({ x: 48, y: height - 96, width: width - 96, height: 1, color: rgb(0.8, 0.83, 0.86) });
    LOREM.forEach((line, li) => {
      page.drawText(line, {
        x: 48,
        y: height - 150 - li * 18,
        size: 11,
        font,
        color: rgb(0.25, 0.29, 0.33),
      });
    });
    page.drawText(footer, { x: 48, y: 40, size: 9, font, color: rgb(0.55, 0.58, 0.62) });
    page.drawText(`Page ${i + 1} of ${n}`, {
      x: width - 110,
      y: 40,
      size: 9,
      font,
      color: rgb(0.55, 0.58, 0.62),
    });
    // corner marks so rotations are obvious
    page.drawText("+", { x: 20, y: height - 34, size: 14, font, color: rgb(0.8, 0.83, 0.86) });
  });
  return doc;
}

async function sampleReport() {
  const doc = await PDFDocument.create();
  for (let i = 0; i < 5; i++) doc.addPage(A4);
  return decorate(doc, {
    title: "Sample Report 2026",
    subtitle: `Sections: Overview · Methodology · Results · Discussion · Appendix`,
    footer: "Local PDF Toolkit — sample-report.pdf (public domain sample)",
  });
}

async function sampleInvoice() {
  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const page1 = doc.addPage(A4);
  doc.addPage(A4); // payment details
  doc.addPage(A4); // terms
  await decorate(doc, {
    title: "Invoice #2026-041",
    subtitle: "ACME Consulting Co. — billed to: Example Corp",
    footer: "Local PDF Toolkit — sample-invoice.pdf (public domain sample)",
  });
  const { height } = page1.getSize();
  const rows = [
    ["Design review workshop", "2 days", "1,600.00"],
    ["Prototype implementation", "5 days", "4,000.00"],
    ["Documentation & handover", "1 day", "800.00"],
    ["Total due (net 30)", "", "6,400.00"],
  ];
  rows.forEach(([item, qty, amount], i) => {
    const y = height - 240 - i * 26;
    const isTotal = i === rows.length - 1;
    page1.drawText(item, { x: 48, y, size: 11, font: isTotal ? bold : font, color: rgb(0.2, 0.24, 0.28) });
    page1.drawText(qty, { x: 330, y, size: 11, font, color: rgb(0.35, 0.4, 0.45) });
    page1.drawText(amount, { x: 430, y, size: 11, font: isTotal ? bold : font, color: rgb(0.2, 0.24, 0.28) });
    page1.drawLine({
      start: { x: 48, y: y - 8 },
      end: { x: 547, y: y - 8 },
      thickness: isTotal ? 1.2 : 0.5,
      color: rgb(0.82, 0.85, 0.88),
    });
  });
  return doc;
}

mkdirSync(OUT, { recursive: true });
writeFileSync(new URL("sample-report.pdf", `file://${OUT}`).pathname, await sampleReport().then((d) => d.save()));
writeFileSync(new URL("sample-invoice.pdf", `file://${OUT}`).pathname, await sampleInvoice().then((d) => d.save()));
console.log("samples written to public/samples/");
